text:
{
  "questions": [
    {
      "header": "数据来源",
      "id": "data_source",
      "question": "任务书允许自选公开数据，课件写的是“使用提供的数据”；目前工作区没有数据，计划采用哪种口径？",
      "options": [
        {
          "label": "自主选择公开数据 (Recommended)",
          "description": "以 COIL-100、TVSum 等公开资源设计实验，记录来源与改编方式。"
        },
        {
          "label": "以教师提供数据为准",
          "description": "按教师清单设计，数据未到位前先准备代码和报告结构。"
        },
        {
          "label": "已有其他本地数据",
          "description": "你提供数据位置或说明后，优先评估和复用现有资源。"
        }
      ]
    },
    {
      "header": "完成深度",
      "id": "experiment_depth",
      "question": "你希望这次实验完成到什么深度？",
      "options": [
        {
          "label": "扎实可复现 (Recommended)",
          "description": "完成三个指定模型、足量查询、完整验收和案例分析，报告可复核。"
        },
        {
          "label": "最低完整交付",
          "description": "控制数据与查询规模，满足全部课程要求，优先缩短完成时间。"
        },
        {
          "label": "增加研究对比",
          "description": "在必做实验之外增加基线、参数对照或消融分析，投入更多运行和写作时间。"
        }
      ]
    },
    {
      "header": "时间约束",
      "id": "deadline",
      "question": "这份执行与写作计划需要按什么时间约束安排？",
      "options": [
        {
          "label": "暂无硬截止 (Recommended)",
          "description": "按阶段验收推进，以结果完整可靠为先，不虚设完成日期。"
        },
        {
          "label": "一周内完成",
          "description": "压缩探索范围，尽早锁定数据和方法，实验与写作同步推进。"
        },
        {
          "label": "三天内完成",
          "description": "优先核心交付，使用较小规模并减少非必要扩展。"
        }
      ]
    }
  ]
}

{
  "questions": [
    {
      "header": "研究重点",
      "id": "research_focus",
      "question": "增加研究对比时，你希望把精力放在哪里？",
      "options": [
        {
          "label": "三个实验均衡对比 (Recommended)",
          "description": "图像比较池化方法，视频比较时序建模，摘要比较长度预算与简单基线；均使用预训练模型。"
        },
        {
          "label": "重点研究视频检索",
          "description": "图像与摘要完成核心要求，集中分析采样率、时间顺序、编辑扰动和难负样本。"
        },
        {
          "label": "重点研究视频摘要",
          "description": "图像与检索完成核心要求，集中分析摘要预算、片段选择和人工标注评价。"
        }
      ]
    },
    {
      "header": "资源位置",
      "id": "asset_location",
      "question": "大型数据、权重和特征缓存放在哪里？当前 C/D/E/F 盘剩余空间约为 21/12/107/158GB。",
      "options": [
        {
          "label": "E盘独立资源目录 (Recommended)",
          "description": "使用 E:\\MultimediaCourseAssets；当前工作区保留代码、配置、图表和报告。"
        },
        {
          "label": "F盘独立资源目录",
          "description": "使用 F:\\MultimediaCourseAssets；当前工作区保留代码、配置、图表和报告。"
        },
        {
          "label": "全部放当前工作区",
          "description": "资源与代码放一起，但需严格限制视频下载与缓存规模。"
        }
      ]
    }
  ]
}
